// Lee la respuesta del Agente redactor, valida el contrato JSON y expone
// titulo / resumen / prompt_imagen para los nodos siguientes.

const text = items[0].json.content[0].text;

// Limpiar bloques de markdown si los hay
const clean = text
  .replace(/```json\n?/g, '')
  .replace(/```\n?/g, '')
  .trim();

// Parsear con manejo de errores explícito
let parsed;
try {
  parsed = JSON.parse(clean);
} catch (e) {
  throw new Error(
    `El Agente redactor devolvió un JSON inválido: ${clean.substring(0, 200)}`
  );
}

// El redactor puede rechazar la noticia rellenando el campo "error".
// Si lo hace, cortamos aquí: no tiene sentido generar imagen ni publicar.
if (parsed.error) {
  throw new Error(`El Agente redactor rechazó la noticia: ${parsed.error}`);
}

// Verificación defensiva de los campos obligatorios
const faltan = ['titulo', 'resumen', 'prompt_imagen'].filter(k => !parsed[k]);
if (faltan.length > 0) {
  throw new Error(
    `Respuesta incompleta del Agente redactor. Campos vacíos: ${faltan.join(', ')}`
  );
}

return [{ json: parsed }];

