// Deduplicación: descarta artículos cuya URL ya se publicó en ciclos anteriores.
// El histórico vive en el static data del workflow (persistido por n8n en su BD),
// no en un fichero del contenedor.

const staticData = $getWorkflowStaticData('global');
const publicadas = staticData.publicadas || [];

// Si los feeds no han devuelto nada, eso SÍ es un fallo real: lo propagamos
// para que el Error Trigger avise.
if (items.length === 0) {
  throw new Error('Los feeds RSS no han devuelto ningún artículo. Revisar las URLs de los feeds o la conectividad.');
}

// Filtrar artículos cuya URL ya esté en el histórico
const nuevas = items.filter(item => {
  const link = item.json.link;
  return link && !publicadas.includes(link);
});

// Que no haya noticias nuevas es el caso NORMAL en la mayoría de ejecuciones
// (el feed cambia más despacio que el ciclo del agente). No es un error:
// terminamos el ciclo en silencio devolviendo una lista vacía.
if (nuevas.length === 0) {
  console.log(
    `Sin noticias nuevas. Artículos en feeds: ${items.length}. ` +
    `Ya publicadas: ${publicadas.length}. Fin del ciclo.`
  );
  return [];
}

return nuevas;

// Construir el listado formateado que recibirá Claude evaluador
const articles = items;

const formatted = articles.map((item, index) => {
  const d = item.json;
  const extracto = (d['content:encodedSnippet'] || d.contentSnippet || '').substring(0, 300);
  const cats = Array.isArray(d.categories) ? d.categories.join(', ') : 'Sin categorías';
  const fecha = d.pubDate || d.isoDate || 'Sin fecha';

  return `[${index}] TÍTULO: ${d.title || 'Sin título'}
EXTRACTO: ${extracto}
CATEGORÍAS: ${cats}
FECHA: ${fecha}`;
}).join('\n\n---\n\n');

// Devolver un único item con el texto formateado para Claude
// y los artículos originales preservados para el lookup posterior
return [{
  json: {
    articulos_texto: formatted,
    articulos_originales: articles.map(item => item.json),
    total_articulos: articles.length
  }
}];

