// 1. Coger la respuesta del Agente evaluador
const text = items[0].json.content[0].text;

// 2. Limpiar bloques markdown por si Claude los añadió
const clean = text
  .replace(/```json\n?/g, '')
  .replace(/```\n?/g, '')
  .trim();

// 3. Parsear el JSON a objeto JavaScript con manejo de errores
let evaluacion;
try {
  evaluacion = JSON.parse(clean);
} catch (e) {
  throw new Error(`El Agente evaluador devolvió un JSON inválido: ${clean.substring(0, 200)}`);
}

// 4. Verificar que el evaluador devolvió al menos una noticia
if (!evaluacion.seleccionadas || evaluacion.seleccionadas.length === 0) {
  throw new Error('El Agente evaluador no devolvió ninguna noticia seleccionada');
}

// 5. Coger la GANADORA (primera del array = mejor puntuación)
const ganadora = evaluacion.seleccionadas[0];

// 6. Recuperar los artículos originales desde el nodo de preparación (lookup)
const articulosOriginales = $('Preparar artículos para evaluación').first().json.articulos_originales;

const articuloCompleto = articulosOriginales[ganadora.indice];

if (!articuloCompleto) {
  throw new Error(
    `El índice ${ganadora.indice} no existe en la lista original ` +
    `(hay ${articulosOriginales.length} artículos)`
  );
}

// 7. Devolver el artículo completo + metadatos del evaluador para auditoría
return [{
  json: {
    ...articuloCompleto,
    _evaluacion: {
      puntuacion: ganadora.puntuacion_total,
      justificacion: ganadora.justificacion,
      candidatas_consideradas: evaluacion.seleccionadas.length,
      todas_candidatas: evaluacion.seleccionadas
    }
  }
}];

// 1. Recuperar la URL del artículo publicado desde el nodo Parsear selección
const link = $('Parsear selección').first().json.link;
const titulo = $('Parsear selección').first().json.title;

if (!link) {
  throw new Error('No se ha podido recuperar el link del artículo publicado');
}

// 2. Acceder al almacenamiento persistente del workflow (BD de n8n)
const staticData = $getWorkflowStaticData('global');
const publicadas = staticData.publicadas || [];

// 3. Añadir la nueva URL al histórico (evitar duplicados por seguridad)
if (!publicadas.includes(link)) {
  publicadas.push(link);
}

// 4. Limitar histórico a las últimas 200 URLs (evitar crecimiento ilimitado)
const MAX_HISTORY = 200;
if (publicadas.length > MAX_HISTORY) {
  publicadas.splice(0, publicadas.length - MAX_HISTORY);
}

// 5. Guardar de vuelta en staticData (se persiste al terminar la ejecución)
staticData.publicadas = publicadas;

// 6. Devolver info de auditoría
return [{
  json: {
    publicada: link,
    titulo: titulo,
    total_en_historico: publicadas.length,
    timestamp: new Date().toISOString()
  }
}];

